head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.cnt = 0;
scwin.prevRow = -1;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name ins_search
 * @description 다운로드IP체크  목록 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    // 데이터셋 초기화
    dts_List.removeAll();

    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    cmb_ACTIV_YN.setDisabled(false);
};

/**
 * @method
 * @name new
 * @description 조회버튼 클릭시 신규등록을 위한 dataset 세팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.new = async function() {
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_List.insertRow();
    const toDay = $c.ut.cGetToday("yyyymmdd");
    edt_PROCS_DD.setValue(toDay);
    fn_CtrlBtn_temp("insert");
    cmb_ACTIV_YN.setValue("Y");
    cmb_ACTIV_YN.setDisabled(true);
    txb_IP_ADDR.setDisabled(false);
    cmb_DNLD_GRP_TP_CD.setValue("01");
    if (document.getElementById("btn_file")) {
        btn_file.setDisabled(true); // 첨부파일
        btn_file.setBackgroundImage("../img/ins/btn_file_d.gif");
    }

    // 중복체크버튼
    btn_dupl.show("");
    txb_dupl.setValue("N");
};

/**
 * @method
 * @name ins_process
 * @description 다운로드IP체크 정보를 저장 , 수정 한다. screenProcsTpCd 02,03
 * @param {String} screenProcsTpCd screenProcsTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_process = async function(screenProcsTpCd) {
    if (screenProcsTpCd === '02') {
        // 저장

        if (edt_PROCS_DD.getValue() === "" || edt_PROCS_DD.text.indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "등록일"));
            edt_PROCS_DD.focus();
            return false;
        }
        if (txb_IP_ADDR.getValue() === "" || txb_IP_ADDR.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "IP"));
            txb_IP_ADDR.focus();
            return false;
        }
        if (txb_dupl.value === "N") {
            await $c.win.alert('IP중복체크를 확인해주세요.');
            txb_IP_ADDR.focus();
            return false;
        }
        if (!confirm('다운로드IP체크 정보를 저장 하시겠습니까?')) {
            return false;
        }
        trs_save.KeyName = "toinb_dataid4";
        // [전환검토] trs_save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     EMP_NO : js_emp_no,
        //     EMP_NM : js_emp_nm
        // };
        const sbmOptions = {
            id : "sbm_trs_save",
            action : "/DownLoadInfoAction.do",
            ref : "dts_List",
            target : "trs_save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
    if (screenProcsTpCd === '03') {
        // 수정

        if (!$c.cp.isModified(dts_List)) {
            await $c.win.alert("변경된 데이터가 없습니다.");
            return;
        }
        if (edt_PROCS_DD.getValue() === "" || edt_PROCS_DD.text.indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "등록일"));
            edt_PROCS_DD.focus();
            return false;
        }
        if (txb_IP_ADDR.getValue() === "" || txb_IP_ADDR.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "IP"));
            txb_IP_ADDR.focus();
            return false;
        }
        if (!confirm('다운로드IP체크 정보를 수정 하시겠습니까?')) {
            return false;
        }
        trs_save.KeyName = "toinb_dataid4";
        // [전환검토] trs_save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     EMP_NO : js_emp_no,
        //     EMP_NM : js_emp_nm
        // };
        const sbmOptions = {
            id : "sbm_trs_save",
            action : "/DownLoadInfoAction.do",
            ref : "dts_List",
            target : "trs_save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
    if (screenProcsTpCd === '04') {
        // 삭제

        dts_List.setCellData(dts_List.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
        if (!confirm('다운로드IP체크 정보를 삭제 하시겠습니까?')) {
            return false;
        }
        trs_save.KeyName = "toinb_dataid4";
        // [전환검토] trs_save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     EMP_NO : js_emp_no,
        //     EMP_NM : js_emp_nm
        // };
        const sbmOptions = {
            id : "sbm_trs_save",
            action : "/DownLoadInfoAction.do",
            ref : "dts_List",
            target : "trs_save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**********************************************
 * 함수명   : fn_GetParam
 * 설명       : 전달값을 정의한다.
 ***********************************************/
scwin.arrPar = new Array();

/**
 * @method
 * @name getParam
 * @description get Param 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // 표준코드 OR 발행기관 코드
    scwin.arrPar[1] = txb_param2.getValue();

    // alert(arrPar[0] + " " + arrPar[1]);
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name checkDupl
 * @description IP 중복검사 한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkDupl = async function() {

    // alert(url);
    const sbmOptions = {
        id : "sbm_dts_Simbol",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Simbol=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    fn_CtrlBtn_temp("no_data");

    // fn_setFromToDate(1, edt_pPROCS_DD_SDATE, edt_pPROCS_DD_EDATE);

    txb_param1.hide();
    txb_param2.hide();
    txb_dupl.hide();
    ins_combo_set(dts_DNLD_GRP_TP_CD, "ULDINS26600.xml", SCREN_PROCS_TP_CD_01, "04204", "NODEFAULT"); // 다운로드그룹구분
    btn_dupl.hide();
};

/**
 * @method
 * @name btn_file_onclick
 * @description 「첨부파일확인」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_file_onclick = function() {
    /*
    txb_param1 에는 신청ID
    txb_param2 에는 구분값을 넣는데..
     + "1 : 발행기관신청, 팩스-발행기관신청 \n"
     + "2 : 표준코드신청, 팩스-표준코드신청 \n"
     + "3 : 팩스-다운로드IP 로 값을 넣어주세요.\n"
     */
    txb_param1.setValue(txb_IP_ADDR.getValue()); // IP_ADDR
    txb_param2.setValue("3");
    fn_GetPar = scwin.getParam;
    ins_popupOpen("", "", "ULDINS91100", "첨부파일", "655", "350");
};

/**
 * @method
 * @name img_PROCS_DD_onclick
 * @description img_PROCS_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_PROCS_DD_onclick = function() {
    popUpCalendar2(edt_PROCS_DD);
};

/**
 * @method
 * @name trs_save_OnSuccess
 * @description save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_save_OnSuccess = async function() {
    await $c.win.alert($c.stf.getMessageParam("MSG-A001", "다운로드IP체크 관리"));
    await scwin.ins_search();
};

/**
 * @method
 * @name trs_save_OnFail
 * @description save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_save_OnFail = function() {
    alert_tr_error(trs_save);
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    if (dts_List.errorMsg) {
        await $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    scwin.cnt = rowcount;
    if (scwin.cnt === 0) fn_CtrlBtn_temp("no_data");

    btn_dupl.hide();
    txb_dupl.setValue("N");
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    await $c.win.alert(dts_List);
    scwin.cnt = 0;
    fn_CtrlBtn_temp("no_data");
};

/**
 * @method
 * @name dts_List_OnRowPosChanged
 * @description List On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnRowPosChanged = function(row) {
    if (dts_List.getRowStatus(row) === 1) return;
    dts_List.undoRow(scwin.prevRow);
    scwin.prevRow = row;
    fn_CtrlBtn_temp("update");
    txb_IP_ADDR.setDisabled(true);
};

/**
 * @method
 * @name btn_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function() {
    await scwin.ins_search();
};

/**
 * @method
 * @name btn_new_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_new_onclick = async function() {
    await scwin.new();
};

/**
 * @method
 * @name btn_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function() {
    await scwin.ins_process("02");
};

/**
 * @method
 * @name btn_modify_onclick
 * @description 「수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_modify_onclick = async function() {
    await scwin.ins_process("03");
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delete_onclick = async function() {
    await scwin.ins_process("04");
};

/**
 * @method
 * @name img_pPROCS_DD_SDATE_onclick
 * @description img_pPROCS_DD_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_pPROCS_DD_SDATE_onclick = function() {
    popUpCalendar2(edt_pPROCS_DD_SDATE);
};

/**
 * @method
 * @name img_pPROCS_DD_EDATE_onclick
 * @description img_pPROCS_DD_EDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_pPROCS_DD_EDATE_onclick = function() {
    popUpCalendar2(edt_pPROCS_DD_EDATE);
};

/**
 * @method
 * @name txb_pIP_ADDR_onkeyup
 * @description txb_pIP_ADDR 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_pIP_ADDR_onkeyup = async function() {
    if (txb_pIP_ADDR.getValue() === "") {

    } else {
        if (window.event.keyCode === 13) {
            await scwin.ins_search();
        } else {

        }
    }
};

/**
 * @method
 * @name btn_dupl_onclick
 * @description 「중복체크」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_dupl_onclick = async function() {
    if (txb_IP_ADDR.getValue() === "" || txb_IP_ADDR.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "IP"));
        txb_IP_ADDR.focus();
        return;
    }
    await scwin.checkDupl();
};

/**
 * @method
 * @name dts_Simbol_OnLoadCompleted
 * @description dts_Simbol 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Simbol_OnLoadCompleted = async function(rowcount) {
    if (rowcount === 0) {
        await $c.win.alert(" 사용할 수 있습니다. [ IP 중복 체크 ]");
        txb_dupl.setValue("Y");
    } else {
        await $c.win.alert(" 이미 사용 중 입니다.  [ IP 중복 체크 ]");
        txb_dupl.setValue("N");
    }
};
